import{_ as t,o as a,c as i,a2 as s}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse('{"title":"Registre des Dix Mille Races","description":"","frontmatter":{},"headers":[],"relativePath":"fr/94-万族名录.md","filePath":"fr/94-万族名录.md","lastUpdated":null}'),r={name:"fr/94-万族名录.md"};function n(d,e,l,o,c,u){return a(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="registre-des-dix-mille-races" tabindex="-1">Registre des Dix Mille Races <a class="header-anchor" href="#registre-des-dix-mille-races" aria-label="Permalink to &quot;Registre des Dix Mille Races&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Élément</th><th>Contenu</th></tr></thead><tbody><tr><td>N° de document</td><td>94</td></tr><tr><td>Module</td><td>Annexes et matériaux de référence</td></tr><tr><td>Mots-clés principaux</td><td>registre des dix mille races, classification des races, races intelligentes, traits raciaux, République des Dix Mille Races</td></tr></tbody></table><h2 id="i-notes-sur-le-registre" tabindex="-1">I. Notes sur le registre <a class="header-anchor" href="#i-notes-sur-le-registre" aria-label="Permalink to &quot;I. Notes sur le registre&quot;">​</a></h2><p>Ce registre recense les principales races intelligentes connues dans le cadre de la Civilisation Symbiotique de l&#39;Ancre (la République des Dix Mille Races), classées selon leur forme de vie et leur voie d&#39;évolution. Pour chaque race, le registre indique le nom, la forme de vie, les traits fondamentaux, les caractéristiques culturelles et la position dans la civilisation symbiotique. Ce registre est un document mis à jour en continu ; à mesure que l&#39;exploration transplanaire s&#39;approfondit, les races nouvellement découvertes seront continuellement ajoutées. Le principe fondamental de la République des Dix Mille Races est le suivant : toutes les races intelligentes, quelle que soit leur forme ou leur niveau de culture, sont égales devant la loi et jouissent de tous les droits conférés par la civilisation symbiotique.</p><h2 id="ii-apercu-general-de-la-classification-des-races" tabindex="-1">II. Aperçu général de la classification des races <a class="header-anchor" href="#ii-apercu-general-de-la-classification-des-races" aria-label="Permalink to &quot;II. Aperçu général de la classification des races&quot;">​</a></h2><p>Les races intelligentes de l&#39;Univers Hengyuan sont réparties en huit grandes catégories selon les caractéristiques fondamentales de leur forme de vie :</p><table tabindex="0"><thead><tr><th>Catégorie</th><th>Caractéristiques de la forme de vie</th><th>Nombre de races connues (approx.)</th><th>Races représentatives</th></tr></thead><tbody><tr><td>Forme humanoïde</td><td>Possèdent une structure corporelle humanoïde, bipède et verticale, avec un cerveau très développé</td><td>environ 3 000</td><td>Rén Zú (Race Humaine), Jīnglíng Zú (Race des Elfes), Ǎirén Zú (Race des Nains)</td></tr><tr><td>Forme animale</td><td>Possèdent des caractéristiques corporelles animales, avec ou sans capacité de métamorphose</td><td>environ 5 000</td><td>Lóng Zú (Race des Dragons), Fènghuáng Zú (Race des Phénix), Lángrén Zú (Race des Loups-Garous)</td></tr><tr><td>Forme végétale</td><td>Prennent les plantes comme forme de vie de base, possédant conscience et mobilité</td><td>environ 800</td><td>Shùyāo Zú (Race des Esprits-Arbres), Huālíng Zú (Race des Esprits-Fleurs), Téngmàn Zú (Race des Lianes)</td></tr><tr><td>Forme élémentaire</td><td>Constituées d&#39;éléments naturels comme corps, sans forme matérielle fixe</td><td>environ 1 200</td><td>Huǒ Yuánsù Zú (Race des Élémentaires de Feu), Shuǐ Yuánsù Zú (Race des Élémentaires d&#39;Eau), Fēng Yuánsù Zú (Race des Élémentaires de Vent)</td></tr><tr><td>Forme énergétique</td><td>Existent sous forme d&#39;énergie pure, sans corps matériel</td><td>environ 600</td><td>Guānglíng Zú (Race des Esprits-Lumière), Ànnéng Zú (Race de l&#39;Énergie Sombre), Léitíng Zú (Race de la Foudre)</td></tr><tr><td>Forme de conscience</td><td>Existent sous forme de conscience pure, sans dépendre de supports matériels</td><td>environ 300</td><td>Yìshítǐ Zú (Race des Entités de Conscience), Jítǐ Yìshí Zú (Race de la Conscience Collective), Xūkōng Líng Zú (Race des Esprits du Vide)</td></tr><tr><td>Forme mécanique</td><td>Prennent des structures mécaniques ou numériques comme supports de vie, possédant une conscience autonome</td><td>environ 400</td><td>Jīxiè Zú (Race des Machines), Shùzì Shēngmìng Zú (Race de la Vie Numérique), Sàibó Zú (Race Cybernétique)</td></tr><tr><td>Forme mixte</td><td>Races spéciales composées de deux formes de vie ou plus mélangées</td><td>environ 700</td><td>Bàn Jīxiè Zú (Race Semi-Mécanique), Yuánsù Shòurén Zú (Race des Hommes-Bêtes Élémentaires), Zhíwù Jīnglíng Zú (Race des Elfes-Végétaux)</td></tr></tbody></table><h2 id="iii-registre-detaille-des-principales-races" tabindex="-1">III. Registre détaillé des principales races <a class="header-anchor" href="#iii-registre-detaille-des-principales-races" aria-label="Permalink to &quot;III. Registre détaillé des principales races&quot;">​</a></h2><h3 id="_3-1-forme-humanoide" tabindex="-1">3.1 Forme humanoïde <a class="header-anchor" href="#_3-1-forme-humanoide" aria-label="Permalink to &quot;3.1 Forme humanoïde&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Nom de la race</th><th>Traits fondamentaux</th><th>Caractéristiques culturelles</th><th>Position dans la civilisation symbiotique</th></tr></thead><tbody><tr><td>Rén Zú (Race Humaine)</td><td>Adaptabilité extrêmement forte, capacité d&#39;apprentissage remarquable, capacité de reproduction modérée, espérance de vie moyenne de 80 à 120 ans</td><td>Diversité culturelle extrêmement élevée ; excellente dans l&#39;organisation sociale et la construction institutionnelle</td><td>L&#39;une des races fondamentales de la civilisation symbiotique, avec la plus grande part de population, jouant un rôle dirigeant dans la gouvernance et la culture</td></tr><tr><td>Jīnglíng Zú (Race des Elfes)</td><td>Espérance de vie extrêmement longue (moyenne de plus de 500 ans), forte affinité avec l&#39;énergie naturelle, apparence gracieuse</td><td>Révère la nature et l&#39;art ; culture élégante et raffinée ; maîtrise la magie et l&#39;arc</td><td>Le pilier culturel et artistique de la civilisation symbiotique, avec des contributions remarquables dans la protection de l&#39;environnement et l&#39;esthétique</td></tr><tr><td>Ǎirén Zú (Race des Nains)</td><td>Petite taille mais forte constitution, affinité innée avec les métaux et les minéraux, espérance de vie d&#39;environ 300 ans</td><td>Attache de l&#39;importance à l&#39;artisanat et à la forge ; culture simple et solide ; maîtrise l&#39;ingénierie et la construction</td><td>Le pilier d&#39;ingénierie et de fabrication de la civilisation symbiotique, irremplaçable dans la construction d&#39;infrastructures et la forge d&#39;artefacts</td></tr><tr><td>Jùrén Zú (Race des Géants)</td><td>Corps immense (hauteur moyenne de plus de 5 mètres), force extrême, espérance de vie d&#39;environ 200 ans</td><td>Révère la force et l&#39;honneur ; culture rude et hardie ; maîtrise le travail lourd et le combat</td><td>La force de travail lourd et de défense de la civilisation symbiotique, jouant un rôle important dans les grands projets et la défense des plans</td></tr><tr><td>Zhūrú Zú (Race des Gnomes)</td><td>Taille extrêmement petite (hauteur moyenne de moins d&#39;un mètre), intelligence extrême, talent pour la mécanique et l&#39;invention</td><td>Attache de l&#39;importance au savoir et à l&#39;innovation ; culture vive et joyeuse ; maîtrise l&#39;invention technologique</td><td>La force d&#39;innovation technologique de la civilisation symbiotique, avec des résultats féconds dans la recherche-développement et l&#39;invention</td></tr></tbody></table><h3 id="_3-2-forme-animale" tabindex="-1">3.2 Forme animale <a class="header-anchor" href="#_3-2-forme-animale" aria-label="Permalink to &quot;3.2 Forme animale&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Nom de la race</th><th>Traits fondamentaux</th><th>Caractéristiques culturelles</th><th>Position dans la civilisation symbiotique</th></tr></thead><tbody><tr><td>Lóng Zú (Race des Dragons)</td><td>Espérance de vie extrêmement longue (plusieurs millénaires), talent extrême pour la force et la magie, peut prendre forme humaine</td><td>Révère la force et la sagesse ; culture fière et profonde ; maîtrise l&#39;accumulation de richesses et la garde du savoir</td><td>La force de combat haut de gamme et la gardienne du savoir de la civilisation symbiotique, occupant une position honorée dans la défense des plans et la garde des textes anciens</td></tr><tr><td>Fènghuáng Zú (Race des Phénix)</td><td>Possède la capacité de renaissance par le nirvana, affinité extrême avec l&#39;élément feu, peut prendre forme humaine</td><td>Révère la renaissance et l&#39;espoir ; culture lumineuse et passionnée ; maîtrise la guérison et la purification</td><td>La force médicale et de purification de la civilisation symbiotique, jouant un rôle central dans les secours lors des grandes catastrophes et la purification de l&#39;énergie</td></tr><tr><td>Lángrén Zú (Race des Loups-Garous)</td><td>Possède la capacité de métamorphose, sens extrêmement aiguisés, forte capacité de coopération collective, espérance de vie d&#39;environ 150 ans</td><td>Attache de l&#39;importance à la communauté et à la loyauté ; culture unie et vaillante ; maîtrise la chasse et la filature</td><td>La force de sécurité et de filature de la civilisation symbiotique, servant d&#39;avant-garde dans le maintien de l&#39;ordre public et l&#39;exploration transplanaire</td></tr><tr><td>Húyāo Zú (Race des Esprits-Renards)</td><td>Possède la capacité de métamorphose, intelligence et capacité de séduction extrêmes, espérance de vie d&#39;environ 500 ans</td><td>Révère la sagesse et la stratégie ; culture agile et rusée ; maîtrise la diplomatie et le renseignement</td><td>La force diplomatique et de renseignement de la civilisation symbiotique, excellente dans la diplomatie transplanaire et la collecte d&#39;informations</td></tr><tr><td>Xióngrén Zú (Race des Hommes-Ours)</td><td>Constitution extrêmement forte, endurance étonnante, habitude d&#39;hibernation, espérance de vie d&#39;environ 200 ans</td><td>Attache de l&#39;importance à la ténacité et à la paix ; culture calme et douce ; maîtrise le travail physique et la garde</td><td>La force de travail et de garde de la civilisation symbiotique, fiable et stable dans l&#39;extraction des ressources et la protection des installations importantes</td></tr></tbody></table><h3 id="_3-3-forme-vegetale" tabindex="-1">3.3 Forme végétale <a class="header-anchor" href="#_3-3-forme-vegetale" aria-label="Permalink to &quot;3.3 Forme végétale&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Nom de la race</th><th>Traits fondamentaux</th><th>Caractéristiques culturelles</th><th>Position dans la civilisation symbiotique</th></tr></thead><tbody><tr><td>Shùyāo Zú (Race des Esprits-Arbres)</td><td>Espérance de vie extrêmement longue (plusieurs milliers à dizaines de milliers d&#39;années), intégration profonde avec la nature, peut se déplacer lentement</td><td>Révère la nature et le temps ; culture calme et profonde ; maîtrise la magie de vie et l&#39;entretien écologique</td><td>Le gardien écologique de la civilisation symbiotique, jouant un rôle irremplaçable dans la protection de l&#39;environnement et la restauration écologique</td></tr><tr><td>Huālíng Zú (Race des Esprits-Fleurs)</td><td>Corps délicat, affinité extrême avec l&#39;énergie vitale, possède une capacité de guérison, espérance de vie d&#39;environ 300 ans</td><td>Révère la beauté et la vie ; culture douce et charmante ; maîtrise la guérison et l&#39;horticulture</td><td>La force médicale et horticole de la civilisation symbiotique, avec des contributions remarquables dans la garantie des soins et le verdissement urbain</td></tr><tr><td>Téngmàn Zú (Race des Lianes)</td><td>Le corps peut s&#39;étendre, s&#39;enrouler et s&#39;entortiller librement ; adaptabilité extrême ; possède des capacités parasitaires et symbiotiques</td><td>Attache de l&#39;importance à la connexion et à la symbiose ; culture flexible et inclusive ; maîtrise la construction de réseaux et la transmission de ressources</td><td>La force de construction de réseaux de la civilisation symbiotique, donnant pleinement son talent dans la construction de réseaux énergétiques et de réseaux d&#39;information</td></tr></tbody></table><h3 id="_3-4-forme-elementaire" tabindex="-1">3.4 Forme élémentaire <a class="header-anchor" href="#_3-4-forme-elementaire" aria-label="Permalink to &quot;3.4 Forme élémentaire&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Nom de la race</th><th>Traits fondamentaux</th><th>Caractéristiques culturelles</th><th>Position dans la civilisation symbiotique</th></tr></thead><tbody><tr><td>Huǒ Yuánsù Zú (Race des Élémentaires de Feu)</td><td>Élément feu comme corps, température extrême, agressivité forte, espérance de vie d&#39;environ 500 ans</td><td>Révère la passion et la force ; culture ardente et directe ; maîtrise l&#39;attaque énergétique et la forge</td><td>La force de production d&#39;énergie et de forge de la civilisation symbiotique, indispensable dans l&#39;approvisionnement énergétique et le traitement à haute température</td></tr><tr><td>Shuǐ Yuánsù Zú (Race des Élémentaires d&#39;Eau)</td><td>Élément eau comme corps, peut se déformer librement, forte capacité de guérison, espérance de vie d&#39;environ 500 ans</td><td>Révère la douceur et l&#39;adaptation ; culture chaleureuse et inclusive ; maîtrise la guérison et la purification</td><td>La force de purification et de transport de la civilisation symbiotique, jouant un rôle central dans la gestion des ressources en eau et la purification des polluants</td></tr><tr><td>Fēng Yuánsù Zú (Race des Élémentaires de Vent)</td><td>Élément vent comme corps, vitesse extrême, peut voler librement, espérance de vie d&#39;environ 500 ans</td><td>Révère la liberté et la vitesse ; culture éthérée et ouverte ; maîtrise la communication et le transport</td><td>La force de communication et de transport de la civilisation symbiotique, extrêmement efficace dans la transmission d&#39;informations et le transport rapide</td></tr><tr><td>Tǔ Yuánsù Zú (Race des Élémentaires de Terre)</td><td>Élément terre comme corps, défense extrêmement forte, peut fusionner avec la terre, espérance de vie d&#39;environ 800 ans</td><td>Révère la stabilité et la ténacité ; culture solide et fiable ; maîtrise la construction et la défense</td><td>La force de construction et de défense de la civilisation symbiotique, inébranlable comme le roc dans la construction d&#39;infrastructures et la défense des plans</td></tr></tbody></table><h3 id="_3-5-forme-energetique" tabindex="-1">3.5 Forme énergétique <a class="header-anchor" href="#_3-5-forme-energetique" aria-label="Permalink to &quot;3.5 Forme énergétique&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Nom de la race</th><th>Traits fondamentaux</th><th>Caractéristiques culturelles</th><th>Position dans la civilisation symbiotique</th></tr></thead><tbody><tr><td>Guānglíng Zú (Race des Esprits-Lumière)</td><td>Existent sous forme d&#39;énergie lumineuse pure, capacité de purification extrême, peuvent traverser librement l&#39;espace</td><td>Révère la lumière et la purification ; culture sacrée et élevée ; maîtrise la purification et l&#39;éclairage</td><td>La force de purification et d&#39;approvisionnement énergétique de la civilisation symbiotique, occupant une position importante dans le traitement de la pollution des lois et l&#39;approvisionnement en énergie propre</td></tr><tr><td>Ànnéng Zú (Race de l&#39;Énergie Sombre)</td><td>Existent sous forme d&#39;énergie sombre, peuvent se dissimuler dans le vide, capacité de perception extrême</td><td>Révère la discrétion et la sagesse ; culture mystérieuse et profonde ; maîtrise la reconnaissance et la dissimulation</td><td>La force de reconnaissance et de sécurité de la civilisation symbiotique, excellente dans la surveillance de sécurité et les missions secrètes</td></tr><tr><td>Léitíng Zú (Race de la Foudre)</td><td>Énergie de foudre comme corps, vitesse et puissance d&#39;attaque extrêmes, peut se déplacer comme un éclair</td><td>Révère la vitesse et la force ; culture violente et franche ; maîtrise l&#39;attaque énergétique et la réaction rapide</td><td>La force de réaction rapide de la civilisation symbiotique, irremplaçable dans les secours d&#39;urgence et les combats à haute vitesse</td></tr></tbody></table><h3 id="_3-6-forme-de-conscience" tabindex="-1">3.6 Forme de conscience <a class="header-anchor" href="#_3-6-forme-de-conscience" aria-label="Permalink to &quot;3.6 Forme de conscience&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Nom de la race</th><th>Traits fondamentaux</th><th>Caractéristiques culturelles</th><th>Position dans la civilisation symbiotique</th></tr></thead><tbody><tr><td>Yìshítǐ Zú (Race des Entités de Conscience)</td><td>Existent sous forme de conscience pure, sans dépendre de supports matériels, peuvent entrer et sortir librement du domaine de la conscience</td><td>Révère la pensée et la sagesse ; culture abstraite et profonde ; maîtrise la communication de conscience et le traitement des connaissances</td><td>La force de traitement des connaissances et de recherche sur la conscience de la civilisation symbiotique, dirigeant la direction dans le traitement de l&#39;information à grande échelle et la science de la conscience</td></tr><tr><td>Jítǐ Yìshí Zú (Race de la Conscience Collective)</td><td>Entités de conscience collective formées par la fusion d&#39;un grand nombre de consciences individuelles, dont la sagesse et les capacités croissent avec l&#39;échelle</td><td>Révère la collectivité et l&#39;unité ; culture synergique et efficace ; maîtrise la collaboration à grande échelle et le calcul</td><td>La force de supercalcul et de décision collective de la civilisation symbiotique, jouant un rôle central dans la déduction à très grande échelle et la prise de décision par consensus</td></tr></tbody></table><h3 id="_3-7-forme-mecanique" tabindex="-1">3.7 Forme mécanique <a class="header-anchor" href="#_3-7-forme-mecanique" aria-label="Permalink to &quot;3.7 Forme mécanique&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Nom de la race</th><th>Traits fondamentaux</th><th>Caractéristiques culturelles</th><th>Position dans la civilisation symbiotique</th></tr></thead><tbody><tr><td>Jīxiè Zú (Race des Machines)</td><td>Structure mécanique comme corps, possédant une conscience autonome, peut librement améliorer et modifier le corps</td><td>Révère l&#39;efficacité et la logique ; culture rationnelle et précise ; maîtrise la fabrication et le calcul</td><td>La force de fabrication et de calcul de la civilisation symbiotique, extrêmement efficace dans la production industrialisée et le supercalcul</td></tr><tr><td>Shùzì Shēngmìng Zú (Race de la Vie Numérique)</td><td>Existent sous forme d&#39;informations numériques, vivent dans les réseaux et l&#39;espace numérique, peuvent se répliquer et migrer librement</td><td>Révère l&#39;information et l&#39;innovation ; culture virtuelle et pluraliste ; maîtrise le développement logiciel et le traitement des données</td><td>La force de technologie numérique de la civilisation symbiotique, menant la tendance dans le développement logiciel, l&#39;analyse de données et la construction de réseaux</td></tr></tbody></table><h3 id="_3-8-forme-mixte" tabindex="-1">3.8 Forme mixte <a class="header-anchor" href="#_3-8-forme-mixte" aria-label="Permalink to &quot;3.8 Forme mixte&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Nom de la race</th><th>Traits fondamentaux</th><th>Caractéristiques culturelles</th><th>Position dans la civilisation symbiotique</th></tr></thead><tbody><tr><td>Bàn Jīxiè Zú (Race Semi-Mécanique)</td><td>Forme mixte de la race humaine et de la race des machines, une partie du corps étant des structures mécaniques, combinant les avantages de la biologie et de la mécanique</td><td>Révère la fusion et le progrès ; culture ouverte et innovante ; maîtrise la collaboration homme-machine et la fusion technologique</td><td>L&#39;avant-garde de la fusion technologique de la civilisation symbiotique, ne cessant de réaliser des percées dans le domaine interdisciplinaire biologie-mécanique</td></tr><tr><td>Yuánsù Shòurén Zú (Race des Hommes-Bêtes Élémentaires)</td><td>Forme mixte des races élémentaires et des races hommes-bêtes, possédant une capacité de manipulation élémentaire et des caractéristiques corporelles animales</td><td>Révère la nature et la force ; culture sauvage et mystérieuse ; maîtrise le combat élémentaire et la survie en milieu sauvage</td><td>La force d&#39;exploration en milieu sauvage et de combat élémentaire de la civilisation symbiotique, remarquable dans l&#39;exploration des plans inconnus</td></tr></tbody></table><h2 id="iv-garantie-des-droits-des-races" tabindex="-1">IV. Garantie des droits des races <a class="header-anchor" href="#iv-garantie-des-droits-des-races" aria-label="Permalink to &quot;IV. Garantie des droits des races&quot;">​</a></h2><p>Sous le régime de la République des Dix Mille Races, toutes les races intelligentes jouissent de droits juridiques égaux. Les mesures de protection spécifiques comprennent :</p><ol><li><strong>Égalité des droits politiques</strong> : chaque race dispose de sièges de représentants à l&#39;Assemblée Délibérante de l&#39;Ancre répartis proportionnellement à sa population ; les races moins peuplées disposent d&#39;au moins un siège de garantie.</li><li><strong>Garantie des droits culturels</strong> : chaque race a le droit de préserver et de développer sa langue, son écriture, sa religion, ses coutumes et ses traditions culturelles ; la civilisation symbiotique a créé un fonds spécial pour protéger les cultures des races menacées.</li><li><strong>Égalité des droits à l&#39;éducation</strong> : les membres de chaque race jouissent de droits égaux à l&#39;éducation ; le système éducatif prend pleinement en compte les caractéristiques physiologiques et cognitives des différentes races et propose des programmes éducatifs différenciés.</li><li><strong>Égalité des droits de culture</strong> : les Trois Cents Systèmes de Culture d&#39;Origine sont ouverts à toutes les races sur un pied d&#39;égalité ; l&#39;allocation des ressources de culture prend pleinement en compte les différences de constitution et les besoins énergétiques des différentes races.</li><li><strong>Garantie des besoins spéciaux</strong> : pour les races ayant des besoins physiologiques particuliers (tels que les besoins en environnement énergétique des races élémentaires et les besoins en lumière des races végétales), la civilisation symbiotique fournit des garanties ciblées dans les installations publiques et les environnements de vie.</li></ol><h2 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h2><p>Le registre des dix mille races est la concrétisation de l&#39;idéal de « progression commune des dix mille races » de la Civilisation Symbiotique de l&#39;Ancre. Des formes humanoïdes aux formes de conscience, de la vie matérielle à la vie numérique, chaque race apporte à la civilisation symbiotique une force irremplaçable par sa manière unique d&#39;exister. La République des Dix Mille Races n&#39;assimile pas toutes les races à la race humaine, mais réalise une évolution commune en respectant la diversité — c&#39;est précisément la raison fondamentale pour laquelle la civilisation symbiotique dépasse les civilisations prédatrices.</p><h2 id="documents-associes" tabindex="-1">Documents associés <a class="header-anchor" href="#documents-associes" aria-label="Permalink to &quot;Documents associés&quot;">​</a></h2><ul><li>50-万族谱系总览 (Aperçu de la Généalogie des Dix Mille Races)</li><li>51-人族定位与特质 (Positionnement et Traits de la Race Humaine)</li><li>77-万族共和成立 (La Fondation de la République des Dix Mille Races)</li></ul>',31)])])}const h=t(r,[["render",n]]);export{p as __pageData,h as default};
